<template><div><div class="mb-6 flex flex-wrap items-end justify-between gap-3"><div><h1 class="text-2xl font-semibold">Finance & QuickBooks Import</h1><p class="text-sm text-slate-500">Track income, expenditure and budget performance.</p></div><button @click="download" class="rounded-lg bg-emerald-700 px-4 py-2 text-sm font-semibold text-white">Download Excel-ready CSV</button></div><div class="grid gap-4 md:grid-cols-3"><div v-for="c in cards" :key="c.label" class="rounded-xl border bg-white p-5"><div class="text-xs uppercase text-slate-500">{{c.label}}</div><div class="mt-2 text-2xl font-semibold">UGX {{Number(c.value||0).toLocaleString()}}</div></div></div><div class="mt-6 rounded-xl border bg-white p-5"><h2 class="font-semibold">Import accounting export</h2><p class="mt-1 text-sm text-slate-500">Columns: Date, Type, Account, Category, Project, Reference, Description, Amount, Currency.</p><input type="file" accept=".csv,.txt" @change="file=$event.target.files[0]" class="mt-4"/><button @click="upload" :disabled="!file" class="mt-4 block rounded-lg bg-[#0d1d2d] px-4 py-2 text-white disabled:opacity-40">Import CSV</button><p v-if="message" class="mt-3 text-sm">{{message}}</p></div><div class="mt-6 rounded-xl border bg-white p-5"><h2 class="font-semibold">Expense categories</h2><div v-for="x in summary.by_category||[]" :key="x.category" class="mt-3 flex justify-between border-b pb-2 text-sm"><span>{{x.category||'Uncategorised'}}</span><span>UGX {{Number(x.total).toLocaleString()}}</span></div></div></div></template>
<script setup>
import {onMounted,ref,computed} from 'vue';import api from '../api/client'
const summary=ref({}),file=ref(null),message=ref('');const cards=computed(()=>[{label:'Income',value:summary.value.income},{label:'Expenses',value:summary.value.expense},{label:'Balance',value:summary.value.balance}])
async function load(){const {data}=await api.get('/finance/summary');summary.value=data}
async function upload(){const f=new FormData();f.append('file',file.value);try{const {data}=await api.post('/finance/import',f,{headers:{'Content-Type':'multipart/form-data'}});message.value=`Imported ${data.import.rows_imported} rows.`;load()}catch(e){message.value=e.response?.data?.message||'Import failed.'}}
async function download(){const response=await api.get('/finance/export',{responseType:'blob'});const url=URL.createObjectURL(response.data);const link=document.createElement('a');link.href=url;link.download='finance-transactions.csv';link.click();URL.revokeObjectURL(url)}
onMounted(load)
</script>